// Webhook de cuenta de Chatwoot: evento "message_created" (Ajustes > Integraciones > Webhooks).
const cfg = $('config').first().json;
const faltan = [];
if (!cfg.chatwoot_url) faltan.push('chatwoot_url');
if (!Number(cfg.account_id)) faltan.push('account_id');
if (!cfg.api_url || /COMPLETAR/.test(cfg.api_url)) faltan.push('api_url');
if (faltan.length) throw new Error('Completar en el nodo config: ' + faltan.join(', '));

const b = $('entrada_chatwoot').first().json.body || {};
// Solo mensajes del cliente: se ignoran otros eventos, los salientes (incluidas las respuestas del propio bot) y las notas privadas
if (b.event !== 'message_created') return [];
if (!['incoming', 0, '0'].includes(b.message_type) || b.private) return [];

const conv = b.conversation || {};
const conversationId = String(conv.id || '').trim();
if (!/^\d+$/.test(conversationId)) return [];
const inboxId = Number((b.inbox && b.inbox.id) || conv.inbox_id || 0);
if (!inboxId) return [];

const sender = b.sender || (conv.meta && conv.meta.sender) || {};
const labels = Array.isArray(conv.labels) ? conv.labels : [];
// Inboxes sin telefono (web/API, solo para pruebas): id estable con un codigo de pais inexistente (+99)
const telefono = String(sender.phone_number || '').trim() || ('+99' + String(Number(sender.id) || 0).padStart(8, '0'));

const adjuntos = Array.isArray(b.attachments) ? b.attachments : [];
const tipos = adjuntos.map(a => a.file_type);
const contacto = adjuntos.find(a => a.file_type === 'contact');
const adjunto = tipos.includes('image') ? '[FOTO]'
  : tipos.includes('audio') ? '[AUDIO]'
  : contacto ? '[CONTACTO COMPARTIDO' + (contacto.fallback_title ? ': ' + contacto.fallback_title : '') + ']'
  : tipos.includes('location') ? '[UBICACION]'
  : tipos.includes('video') ? '[VIDEO]'
  : adjuntos.length ? '[ARCHIVO]' : '';
// El bot se calla cuando la conversacion paso a un humano o alguien lo pauso a mano
const etiquetasStop = [cfg.etiqueta_pide_humano, cfg.etiqueta_bot_pausado];

return [{ json: {
  conversation_id: conversationId,
  inbox_id: inboxId,
  contact_id: Number(sender.id) || 0,
  nombre: String(sender.name || '').trim(),
  telefono,
  labels,
  bot_activo: !labels.some(l => etiquetasStop.includes(l)),
  audio_url: String((adjuntos.find(a => a.file_type === 'audio') || {}).data_url || ''),
  msg: { id: String(b.id || $execution.id), texto: [String(b.content || '').trim(), adjunto].filter(Boolean).join(' '), ts: Date.now() },
} }];

// Whisper decide el formato por la extension: las notas de voz de WhatsApp (.oga/.opus) se renombran a .ogg
const item = $input.first();
const bin = item.binary && item.binary.data;
if (bin && !/\.(flac|mp3|mp4|mpeg|mpga|m4a|ogg|wav|webm)$/i.test(bin.fileName || '')) {
  bin.fileName = 'audio.ogg';
  bin.fileExtension = 'ogg';
  bin.mimeType = 'audio/ogg';
}
return [item];

// Toma la lista del buffer (antes de borrarla) y arma un solo texto.
const lista = $('leer_buffer').last().json.mensajes || [];
const msgs = lista.map(s => { try { return JSON.parse(s); } catch (e) { return null; } })
  .filter(Boolean)
  .sort((a, b) => a.ts - b.ts);

const partes = [];
for (const m of msgs) {
  const t = String(m.texto || '').trim() || '[ARCHIVO]';
  if (partes[partes.length - 1] !== t) partes.push(t);
}
return [{ json: { chat_input: partes.join('\n') || '[ARCHIVO]' } }];

