const cfg = $('config').first().json;
const conv = $('normalizar_entrada').first().json;

// 1) Parsear el JSON del agente (con red de seguridad)
const bruto = String($('agente').first().json.output || '').replace(/```json|```/g, '').trim();
let out = null;
try {
  const i = bruto.indexOf('{'), j = bruto.lastIndexOf('}');
  out = JSON.parse(bruto.slice(i, j + 1));
} catch (e) { out = null; }
if (!out || typeof out !== 'object') {
  out = { respuesta: bruto.startsWith('{') ? '' : bruto, estado: 'conversando' };
}

// 2) Limpieza: emojis, ¿ ¡, espacios, punto final
const limpiar = t => String(t || '')
  .replace(/[\u{10000}-\u{10FFFF}]/gu, '')
  .replace(/[ \t]{2,}/g, ' ')
  .replace(/ +([,.!?])/g, '$1')
  .replace(/[¿¡]/g, '')
  .replace(/[ \t]+\n/g, '\n')
  .trim();
const sinPuntoFinal = t => t.replace(/(?<!\.)\.$/, '').trim();

// 3) Burbujas: se corta por doble salto de linea. Maximo 3; lo que sobra se junta en la primera
const partes = limpiar(out.respuesta).split(/\n\s*\n+/).map(x => sinPuntoFinal(x.trim())).filter(Boolean);
const sobran = Math.max(0, partes.length - 3);
const burbujas = [partes.slice(0, sobran + 1).join('\n'), ...partes.slice(sobran + 1)].filter(Boolean);

const handoff = out.estado === 'pide_humano';
if (handoff && !burbujas.length) burbujas.push('Dale, le paso tu consulta a alguien del club que te escribe en un rato');

// 4) Handoff: etiqueta pide-humano (Chatwoot reemplaza TODAS las etiquetas: se conservan las actuales) y nota privada
const labels = [...new Set([...(conv.labels || []), ...(handoff ? [cfg.etiqueta_pide_humano] : [])])];
const nota = [
  'DERIVADO POR EL BOT DE RESERVAS',
  'Motivo: ' + (limpiar(out.motivo_derivacion) || '-'),
  'Nombre: ' + (conv.nombre || '-'),
  'Telefono: ' + conv.telefono,
].join('\n');

return burbujas.map(texto => ({ json: { conversation_id: Number(conv.conversation_id), texto, handoff, labels, nota } }));

// El agente o la API fallaron: avisar a la persona y pasar la charla a alguien del club.
const cfg = $('config').first().json;
const conv = $('normalizar_entrada').first().json;
const err = $input.first().json;
const detalle = String((err.error && (err.error.message || err.error)) || err.message || JSON.stringify(err)).slice(0, 500);
return [{ json: {
  conversation_id: Number(conv.conversation_id),
  texto: 'Disculpá, tuve un problema técnico. Ya le aviso a alguien del club para que te responda por acá',
  handoff: true,
  labels: [...new Set([...(conv.labels || []), cfg.etiqueta_pide_humano])],
  nota: ['ERROR DEL BOT DE RESERVAS', 'Detalle: ' + detalle, 'Nombre: ' + (conv.nombre || '-'), 'Telefono: ' + conv.telefono].join('\n'),
} }];
